function sortTasks(tasks,view=state.view){const sort=state.savedViews?.find(item=>'view:'+item.id===view)?.sort;if(!sort||sort==='manual')return tasks;return tasks.slice().sort((a,b)=>sort==='priority'?a.priority-b.priority:((sort==='due'?a.deadline:a.when)||'9999-12-31').localeCompare((sort==='due'?b.deadline:b.when)||'9999-12-31'));}
